using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public class ContinuousWorldTests
{
 static RegionalRequest Line(WorldSession s,string id,long ax,long ay,long bx,long by,bool clerk=false){var n=s.DiagnosticSnapshot().Atlas!.Anchor;return new(new(id),ContractFixture.Officer,clerk?ContractFixture.Clerk:ContractFixture.Officer,RegionalAction.Move,ContinuousWorld.Point(n,ax,ay),ContinuousWorld.Point(n,bx,by));}
 [Fact] public void AllNationalNodesHaveDeterministicGroundAndUniqueTiles(){var ids=new HashSet<string>();foreach(var n in NationalRoutes.Nodes){var w=ContinuousWorld.Create(n.Id);ContractValidation.Validate(w);var ts=ContinuousWorld.VisibleTiles(ContinuousWorld.Origin(n.Id),200);Assert.Equal(25,ts.Length);Assert.All(ts,t=>Assert.True(ids.Add(t.Id)));Assert.All(w.Region!.Units,u=>Assert.True(ContinuousWorld.Walkable(u.Position)));}Assert.Equal(NationalRoutes.Nodes.Length*25,ids.Count);}
 [Fact] public void AdjacentTilesShareExactEdgeHeights(){foreach(var n in NationalRoutes.Nodes){var tile=ContinuousWorld.TileAt(ContinuousWorld.Origin(n.Id));var a=ContinuousWorld.Surfaces(tile);var b=ContinuousWorld.Surfaces(tile with{X=tile.X+1});var edge=a.SelectMany(t=>new[]{t.A,t.B,t.C}).Where(v=>v.Point.X==(tile.X+1)*ContinuousWorld.Tile).Distinct().OrderBy(v=>v.Point.Y).ToArray();var next=b.SelectMany(t=>new[]{t.A,t.B,t.C}).Where(v=>v.Point.X==edge[0].Point.X).Distinct().OrderBy(v=>v.Point.Y).ToArray();Assert.Equal(edge,next);Assert.All(edge,v=>Assert.Equal(v.HeightMm,ContinuousWorld.Height(v.Point)));}}
 [Fact] public void StreamingHasBoundedResidencyAndNoWorldEffects(){var w=ContinuousWorld.Create();var hash=ContractJson.CanonicalHash(w);foreach(var n in NationalRoutes.Nodes)foreach(var x in new[]{-300000L,0,300000}){Assert.InRange(ContinuousWorld.VisibleTiles(ContinuousWorld.Point(n.Id,x,0),200).Length,1,25);Assert.Empty(ContinuousWorld.VisibleTiles(ContinuousWorld.Point(n.Id,x,0),1000));}Assert.Equal(hash,ContractJson.CanonicalHash(w));}
 [Fact] public void MovementActuallyCrossesThe80mBoundary(){var s=new WorldSession(ContinuousWorld.Create());Assert.Equal(ResultCode.Accepted,s.IssueRegional(Line(s,"request:cross",115000,-85000,135000,-85000),s.Revision).Code);Assert.Equal("applied",s.DiagnosticSnapshot().Region!.Commands.Last().Result);Assert.Equal(200,s.AdvanceTo(200).ReachedAt);Assert.All(s.DiagnosticSnapshot().Region!.Units.Where(u=>u.Commander==ContractFixture.Officer),u=>{Assert.Equal(u.Goal,u.Position);Assert.True(ContinuousWorld.Local(u.Position,"castle").X>80000);});}
 [Theory][InlineData(7)][InlineData(13)][InlineData(55)] public void SavedBoundaryRoutesRestoreAndContinueIdentically(int at){var s=new WorldSession(ContinuousWorld.Create());s.IssueRegional(Line(s,"request:save",115000,-85000,135000,-85000),s.Revision);s.AdvanceTo(at);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"atlas-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);store.Save(s,"stage",s.DiagnosticSnapshot().WorldId,new(.375,1));var host=new WorldSessionHost(new(ContinuousWorld.Create()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("stage"),host.Current,host.Current.Revision));host.Current.SetPaused(false);s.AdvanceTo(220);host.Current.AdvanceTo(220);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Region),ContractJson.Write(host.Current.DiagnosticSnapshot().Region));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Messaging),ContractJson.Write(host.Current.DiagnosticSnapshot().Messaging));}
 [Fact] public void CourierCrossesBoundaryBeforeOfficerActsAndReports(){var s=new WorldSession(ContinuousWorld.Create());s.IssueRegional(Line(s,"request:clerk",195000,-45000,215000,-45000,true),s.Revision);var c=s.DiagnosticSnapshot().Region!.Commands.Single();Assert.Equal("in-transit",c.Result);Assert.Equal("発送済・結果未確認",RegionalBattle.Status(s.DiagnosticSnapshot(),c,ContractFixture.Officer));s.AdvanceTo(500);var w=s.DiagnosticSnapshot();Assert.Equal("applied",w.Region!.Commands.Single().Result);Assert.True(w.Region.Deliveries.Length>=2);Assert.All(w.Region.Units.Where(u=>u.Commander==ContractFixture.Clerk),u=>Assert.Equal(u.Goal,u.Position));Assert.Equal("applied",RegionalBattle.Status(w,w.Region.Commands.Single(),ContractFixture.Officer));}
 [Fact] public void RiverAndCliffCannotBeEnteredButBridgeIsWalkable(){Assert.False(ContinuousWorld.Walkable(ContinuousWorld.Point("castle",60000,85000)));Assert.True(ContinuousWorld.Walkable(ContinuousWorld.Point("castle",125000,85000)));Assert.False(ContinuousWorld.Walkable(ContinuousWorld.Point("castle",245000,205000)));var a=ContinuousWorld.Point("castle",125000,75000);var b=ContinuousWorld.Point("castle",125000,115000);var path=RegionalGround.Plan(a,b,0,atlas:true);RegionalGround.ValidatePath(path,a,b,atlas:true);}
 [Fact] public void CombatAndRetreatUseSameSecondsAcrossTileBoundary(){var s=new WorldSession(ContinuousWorld.Create(lowMorale:true));var r=new RegionalRequest(new("request:engage"),ContractFixture.Officer,ContractFixture.Officer,RegionalAction.Engage,new(0,0),new(0,0));s.IssueRegional(r,s.Revision);s.AdvanceTo(220);var w=s.DiagnosticSnapshot();Assert.NotEmpty(w.Region!.Losses);Assert.Contains(w.Region.Units,u=>u.Commander==ContractFixture.Officer&&u.Phase=="routed");Assert.Equal(w.Region.Losses.Length,w.Region.Losses.Select(l=>(l.At,l.Unit)).Distinct().Count());}
 [Fact] public void UnknownEnemyDoesNotLeakFromRemoteTile(){var w=ContinuousWorld.Create();var enemy=w.Region!.Units.Where(u=>u.Side==1).Select(u=>u with{Position=ContinuousWorld.Point("castle",300000,-250000),Home=ContinuousWorld.Point("castle",300000,-250000),RouteOrigin=ContinuousWorld.Point("castle",300000,-250000),Goal=ContinuousWorld.Point("castle",300000,-250000)}).ToArray();w.Region=w.Region with{Units=w.Region.Units.Where(u=>u.Side==0).Concat(enemy.Select((u,i)=>u with{Position=u.Position with{X=u.Position.X+i*10000},Home=u.Home with{X=u.Home.X+i*10000},Goal=u.Goal with{X=u.Goal.X+i*10000},RouteOrigin=u.RouteOrigin with{X=u.RouteOrigin.X+i*10000}})).ToArray(),Sights=[]};RegionalBattle.Sync(w);Assert.DoesNotContain(RegionalBattle.View(w,ContractFixture.Officer),v=>enemy.Any(u=>u.Id==v.Unit));}
 [Fact] public void OldSaveCannotBeSilentlyReadAsAtlas(){var w=RegionalScenery.Create();var storePath=Path.Combine(Path.GetTempPath(),"atlas-old-"+Guid.NewGuid().ToString("N"));new GenerationSaveStore(storePath,w.Definitions).Save(new(w),"stage",w.WorldId,new(0,1));Assert.Throws<ContractLoadException>(()=>new GenerationSaveStore(storePath,ContinuousWorld.Create().Definitions).Prepare("stage"));}
 [Fact] public void NationalTravelReentersNewRegionWithoutTeleportingOtherOfficers(){var s=new WorldSession(ContinuousWorld.Create());var old=s.DiagnosticSnapshot().Region!.Units.Where(u=>u.Commander!=ContractFixture.Officer).Select(u=>u.Position).ToArray();Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(false,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:national","fork"),s.Revision).Code);s.AdvanceTo(12000);Assert.False(TravelWorld.Active(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);var w=s.DiagnosticSnapshot();Assert.Equal("fork",w.Atlas!.Anchor);Assert.Equal(old,w.Region!.Units.Where(u=>u.Commander!=ContractFixture.Officer).Select(u=>u.Position));Assert.Equal(12000,s.Seconds);Assert.Contains(RegionalBattle.View(w,ContractFixture.Officer),v=>w.Region.Units.Single(u=>u.Id==v.Unit).Side==1&&!v.Live);ContractValidation.Validate(w);}
 [Fact] public void GroundOutsideSettlementIsLazyAndNotLimitedToOldPatch(){var p=ContinuousWorld.Point("castle",1200000,1200000);var ts=ContinuousWorld.VisibleTiles(p,180);Assert.Equal(25,ts.Length);Assert.All(ts,t=>Assert.Equal("world",t.Node));Assert.All(ts.SelectMany(t=>ContinuousWorld.Surfaces(t)),t=>Assert.All(new[]{t.A,t.B,t.C},v=>Assert.Equal(v.HeightMm,ContinuousWorld.Height(v.Point))));}
 [Fact] public void InvalidCameraAndWrongAtlasVersionAreRejected(){var w=ContinuousWorld.Create();w.Atlas=w.Atlas! with{TerrainVersion="wrong"};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));var good=ContinuousWorld.Create();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"atlas-camera-"+Guid.NewGuid().ToString("N")),good.Definitions);Assert.Throws<InvalidDataException>(()=>store.Save(new(good),"stage",good.WorldId,new(0,1,null,new(0,0,double.NaN,0,true,true))));}
 [Fact] public void CameraRoundtripLeavesLegacyPresentationFieldsOptional(){var old=ContractJson.Read<SavePresentation>(System.Text.Encoding.UTF8.GetBytes("{\"DisplayFraction\":0,\"DisplaySpeed\":1}"));Assert.Null(old.WorldCamera);var p=new SavePresentation(.375,10,null,new(100,200,160,30,true,true));Assert.Equal(p,ContractJson.Read<SavePresentation>(ContractJson.Write(p)));}
}
